export const ROLE_NAMES={literature_reader:'文献审阅',code_inspector:'代码检查',planner:'计划编排',experiment_runner:'实验执行',cross_auditor:'交叉核查',reporter:'报告整理'};
const kinds={plan_scheduled:'按计划排程',stage_started:'开始阶段执行',stage_finished:'阶段执行结束',stage_checked:'核对阶段输出',execution_checked:'汇总执行证据',report_written:'写入执行报告',stopped:'结束排程'};
export function activityEvents(report){
 const execution=report?.execution,rows=execution?.events||[];
 return [...(report?.activity||[]),...rows.map((x,index)=>({...x,roles:[x.role],status:x.kind==='stage_started'&&execution.status==='running'&&!rows.slice(index+1).some(y=>y.kind==='stage_finished'&&y.stage===x.stage)?'running':x.kind==='stage_finished'&&x.exit_code!==0?'failed':'completed',title:kinds[x.kind]||x.kind,detail:report.review?.plan?.stages?.find(s=>s.id===x.stage)?.title||x.reason||({completed:'已结束',running:'执行中',failed:'执行受阻',cancelled:'已停止',expired:'已超时'}[x.status]||x.status)||''}))];
}
export function activityView(report,esc){
 const events=activityEvents(report);if(!events.length)return '';
 const active=events.filter(x=>x.status==='running'),last=active.at(-1)||events.at(-1),roles=Object.entries(ROLE_NAMES);
 return `<section class="review-activity" aria-label="审查协作进度"><header><div><h2>${report.status==='reviewing'?'正在协作审查':'审查协作记录'}</h2><p role="status" aria-live="polite">${esc(last.title)}${last.detail?' · '+esc(last.detail):''}</p></div><span>${report.status==='reviewing'||report.execution?.status==='running'?'<span class="online-spinner" aria-hidden="true"></span>':'已记录'}</span></header><div class="review-role-lanes">${roles.map(([id,label])=>{const rows=events.filter(x=>(x.roles||[]).includes(id)),running=rows.some(x=>x.status==='running'),done=rows.some(x=>x.status==='completed');return `<div class="review-role-lane ${running?'running':done?'completed':''}"><span class="review-role-dot" aria-hidden="true"></span><strong>${label}</strong><small>${running?'进行中':done?'已参与':rows.some(x=>x.status==='skipped')?'本次未执行':report.status==='reviewing'?'等待任务':'未执行'}</small></div>`;}).join('')}</div><details class="review-activity-log"><summary>查看 ${events.length} 条活动记录</summary><ol>${events.map(x=>`<li><time>${x.time?esc(new Date(x.time*1000).toLocaleTimeString('zh-CN',{hour12:false})):''}</time><div><strong>${esc(x.title)}</strong><span>${(x.roles||[]).map(id=>esc(ROLE_NAMES[id]||id)).join(' · ')} · ${esc({running:'进行中',completed:'已结束',skipped:'未执行',failed:'未完成'}[x.status]||x.status)}</span>${x.detail?`<p>${esc(x.detail)}</p>`:''}</div></li>`).join('')}</ol></details><p class="online-footnote">活动来自实际请求与执行事件。文献、代码和规划职责共享主审请求；交叉复核按适用条件单独调用。</p></section>`;
}
